  setVar('takingphoto', true);
setVar('takingphotoV2', 'v2');
console.log("takingphoto", true);

  const res = await fetch('https://aiagent.maxsolo.co.uk/snapshot');
  const data = await res.json();

  await new Promise(resolve => setTimeout(resolve, 2000));

  storeVars.waiting_wait = true;
  setVar('imageurl', data.url); // <-- no trailing space
  setVar('takingphoto', false);
  storeVars.waiting_wait = false;

  return { status: 'success', output: data };
}

export async function processRequest(input, ctx) {
  const {
    imagePath,
    prompt = '',
    systemPrompt = '',
  } = input || {};

  if (!imagePath) {
    return {
      status: 'error',
      message: 'imagePath is required',
      input,
      timestamp: new Date().toISOString(),
      output: null,
    };
  }

  const baseUrl = 'https://visionai.maxsolo.co.uk';

  const url = new URL(baseUrl);
  url.searchParams.set('imagePath', String(imagePath));
  url.searchParams.set('prompt', String(prompt));
  url.searchParams.set('systemprompt', String(systemPrompt));

  try {
    const res = await fetch(url.toString());

    if (!res.ok) {
      const text = await res.text();
      console.log('visionai received error body', text);
      return {
        status: 'error',
        message: `visionai error: ${res.status} ${res.statusText}`,
        input,
        timestamp: new Date().toISOString(),
        output: text,
      };
    }

    const visionaiData = await res.json();

    if (ctx && typeof ctx.setVar === 'function') {
      ctx.setVar('visionaiData', visionaiData);
    }

    console.log('visionaiData ok', visionaiData);

    return {
      status: 'success',
      message: 'Request processed',
      input,
      timestamp: new Date().toISOString(),
      output: visionaiData,
    };
  } catch (err) {
    console.log('visionaiData fetch error', err?.message || err);
    return {
      status: 'error',
      message: `Fetch failed: ${err?.message || String(err)}`,
      input,
      timestamp: new Date().toISOString(),
      output: null,
    };
  }
}

async function processRequest() {
  const body = document.querySelector('.ms-apiresults-body');
  if (!body) {
    console.log("no_container");
    return { error: 'no_container' };  
  }

  const buttonId = 'continue-btn-1';

  // 新增檢查：如果按鈕已存在，就不重複新增
  if (document.getElementById(buttonId)) {
    console.log('Button already exists, skipping creation');
    return { status: 'waiting_user_input', nodeId: ctx.node?.id || null, buttonId };
  }

  const btn = document.createElement('button');
  btn.id = buttonId;
  btn.innerText = 'Continue workflow';
  btn.className = 'ms-continue-btn';
  btn.onclick = () => {
    ctx.setVar('waiting_wait', false);
    document.dispatchEvent(new CustomEvent('workflowResume', { detail: { nodeId: ctx.node?.id } }));
    console.log('button click');
  };

  body.appendChild(btn);

  // set waiting flag to pause workflow
  ctx.setVar('waiting_wait', true);
  console.log("set waiting wait", true);
  return { status: 'waiting_user_input', nodeId: ctx.node?.id || null, buttonId };
}

function processRequest() {
  console.log("show text Function");

const body = document.querySelector('.ms-apiresults-body');
  if (!body) return;

  const componentID = 'text-' + Date.now();
  const x = 20;
  const y = 20;
  const width = 'auto';
  const height = 'auto';
  const displayHTML = '<div style="font-size:14px;color:#fff;">Hello from Text Component</div>';

  const wrapper = document.createElement('div');
  wrapper.className = 'ms-apiresults-item';
  wrapper.id = componentID;
  wrapper.style.position = 'absolute';
  wrapper.style.left = x + 'px';
  wrapper.style.top = y + 'px';
  if (width !== 'auto') wrapper.style.width = width;
  if (height !== 'auto') wrapper.style.height = height;

  wrapper.innerHTML = displayHTML;
  body.appendChild(wrapper);

  return {
    componentID,
    x,
    y,
    width,
    height,
    displayHTML
  };
}

async function processRequest(ctx) {
  console.log("show Image Function", ctx.node?.id);

  const body = document.querySelector('.ms-apiresults-body');
  if (!body) {
    console.warn('ms-apiresults-body not found');
    return { error: 'no_container' };
  }

  const componentID = 'img-' + Date.now();
  const x = 0;
  const y = 0;
  const width = '50px';
  const height = '50px';
  const imageURL = "https://maxsolo.co.uk/images/uploads/img_69970ede6e00a3.96022462.jpg";

  try {
    const wrapper = document.createElement('div');
    wrapper.className = 'ms-apiresults-item';
    wrapper.id = componentID;
    wrapper.style.position = 'absolute';
    wrapper.style.left = x + 'px';
    wrapper.style.top = y + 'px';
    wrapper.style.width = width;
    wrapper.style.height = height;

    const img = document.createElement('img');
    img.src = imageURL;
    img.style.width = '100%';
    img.style.height = '100%';
    img.style.objectFit = 'contain';

    wrapper.appendChild(img);
    body.appendChild(wrapper);

    // Save a reference in storeVars for UI or later inspection
    if (typeof ctx.setVar === 'function') {
      ctx.setVar('last_api_component', { id: componentID, imageURL, nodeId: ctx.node?.id || null });
    }

    // Optionally pause the workflow (global flag used by runner)
    // ctx.setVar('waiting_wait', true);

    return { componentID, x, y, width, height, imageURL };
  } catch (err) {
    console.error('processRequest failed', err);
    return { error: String(err) };
  }
}

