async function processRequest(input) {
  const printoutdata = getVar("inputtext") || {};
  console.log("input form START");
storeVars.waiting_wait = true;
  const clientJS = `
    console.log("clientJS input form START");

    let formContainer = document.getElementById('inputFormContainer');
    if (formContainer) {
      console.log("form already exists");
      return;
    }

    formContainer = document.createElement('div');
    formContainer.id = 'inputFormContainer';
    formContainer.style.cssText = \`
      width: 400px; 
      height: 300px; 
      background: #2c3e50; 
      border: 2px solid #34495e; 
      border-radius: 8px; 
      padding: 20px; 
      font-family: -apple-system, BlinkMacSystemFont, sans-serif;
      color: white;
    \`;

    const title = document.createElement('h3');
    title.textContent = 'Data Input Form';
    title.style.cssText = 'margin: 0 0 20px 0; color: #ecf0f1; text-align: center;';
    formContainer.appendChild(title);

    const input = document.createElement('textarea');
    input.id = 'userInputData';
    input.placeholder = 'Enter your data here...';
    input.rows = 8;
    input.style.cssText = \`
      width: 100%; 
      padding: 12px; 
      border: 1px solid #7f8c8d; 
      border-radius: 4px; 
      background: #34495e; 
      color: #ecf0f1; 
      font-family: monospace; 
      font-size: 14px;
      resize: vertical;
      box-sizing: border-box;
    \`;
    formContainer.appendChild(input);

    const submitBtn = document.createElement('button');
    submitBtn.textContent = 'Save to Global Store';
    submitBtn.style.cssText = \`
      width: 100%; 
      padding: 12px; 
      margin-top: 15px; 
      background: #3498db; 
      color: white; 
      border: none; 
      border-radius: 4px; 
      font-size: 16px; 
      font-weight: bold; 
      cursor: pointer;
      transition: background 0.3s;
    \`;

    const statusDiv = document.createElement('div');
    statusDiv.id = 'formStatus';
    statusDiv.style.cssText = 'margin-top: 10px; padding: 8px; border-radius: 4px; font-size: 12px; text-align: center; display: none;';

    submitBtn.onclick = () => {
      const inputValue = input.value.trim();
      if (!inputValue) {
        statusDiv.textContent = 'Please enter some data!';
        statusDiv.style.background = '#e74c3c';
        statusDiv.style.display = 'block';
        return;
      }

      try {
        setGlobalVar("inputtext", inputValue);
;
        statusDiv.textContent = '✅ Data saved to global var: inputtext';
        statusDiv.style.background = '#27ae60';
        statusDiv.style.display = 'block';

        setTimeout(() => {
          statusDiv.style.display = 'none';
storeVars.waiting_wait = false
        }, 3000);
      } catch (error) {
        statusDiv.textContent = 'Error: ' + error.message;
        statusDiv.style.background = '#e74c3c';
        statusDiv.style.display = 'block';
      }
    };

    formContainer.appendChild(submitBtn);
    formContainer.appendChild(statusDiv);

    const container = document.getElementById('ms-apiresults-body');
    if (!container) {
      console.error('Container not found');
      return;
    }
    container.appendChild(formContainer);

    const existingData = ${JSON.stringify(printoutdata)};
    if (existingData && Object.keys(existingData).length > 0) {
      input.value = JSON.stringify(existingData, null, 2);
    }

    console.log("clientJS input form finish");
  `;

  return {
    status: "ready",
    clientJS,
  };
}

