async function processRequest(input) {
  const printoutdata = getVar("askresponse") || {};
  console.log("new ask box START");

  const clientJS = `
    console.log("clientJS ask box START");

    function createPrintDataMachine(container) {
      const printDiv = document.createElement('div');
      printDiv.id = 'printDataMachine';
      printDiv.style.cssText = 'width: 400px; height: 400px; overflow: auto; background: #515151; border: 1px solid #dee2e6; padding: 12px; font-family: monospace; font-size: 12px; white-space: pre-wrap;';
      container.appendChild(printDiv);
      return printDiv;
    }

    const container = document.getElementById('ms-apiresults-body');
    if (!container) {
      console.error('Container not found');
      return;
    }

    let printDiv = document.getElementById('printDataMachine');
    const isNew = !printDiv;

    if (isNew) {
      console.log("new ask box create");
      printDiv = createPrintDataMachine(container);
    }

    const printoutdata = ${JSON.stringify(printoutdata)};
    let formattedData = '';
    if (typeof printoutdata === 'object' && printoutdata !== null) {
      formattedData = JSON.stringify(printoutdata, null, 2);
    } else {
      formattedData = JSON.stringify(printoutdata, null, 2) || 'No data';
    }

    printDiv.innerHTML = '<pre>' + formattedData + '</pre>';
    console.log("clientJS ask box finish");
  `;

  return {
    status: "ready",
    clientJS,
  };
}

